553	    /**
554	     * The fixed inclusive 4-digit postcode range allowed for each region, keyed by region code
555	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
556	     */
557	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
558	        "NSW", new int[] {2000, 2099},
559	        "VIC", new int[] {3000, 3099},
560	        "QLD", new int[] {4000, 4099});
561	
562	    /**
563	     * Validates an owner's postcode, but only when one is supplied. A {@code null} or blank postcode
564	     * is optional and accepted, keeping the create contract backward-compatible. When present the
565	     * value must be 4 digits and, when the owner's city has a known region (Sydney->NSW,
566	     * Melbourne->VIC, Brisbane->QLD), must fall within that region's inclusive range (NSW 2000-2099,
567	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
568	     *
569	     * @param postcode the raw postcode value as submitted, may be {@code null}
570	     * @param city     the owner's city, used to resolve the region whose range applies
571	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for
572	     *                                  the city's region
573	     */
574	    private void validatePostcode(String postcode, String city) {
575	        if (isBlank(postcode)) {
576	            return;
577	        }
578	        if (!postcode.matches("[0-9]{4}")) {
579	            throw new InvalidPostcodeException(postcode, city);
580	        }
581	        String region = region(city);
582	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
583	        if (range != null) {
584	            int value = Integer.parseInt(postcode);
585	            if (value < range[0] || value > range[1]) {
586	                throw new InvalidPostcodeException(postcode, city);
587	            }
588	        }
589	    }
590	
591	    /**
592	     * Derives an owner's region from its city using the fixed city-to-region table (Sydney->NSW,
593	     * Melbourne->VIC, Brisbane->QLD), returning {@code null} when the city is not in the table.
594	     *
595	     * @param city the owner's city
596	     * @return the region code, or {@code null} when the city has no known region
597	     */
598	    private String region(String city) {
599	        if (city == null) {
600	            return null;
601	        }
602	        return switch (city) {
603	            case "Sydney" -> "NSW";
604	            case "Melbourne" -> "VIC";
605	            case "Brisbane" -> "QLD";
606	            default -> null;
607	        };
608	    }
609	
610	    /**
611	     * The number of national (subscriber) digits an E.164 number must carry for a given country
612	     * calling code, keyed by that code (without the leading '+'). Australia ('+61') requires 9
613	     * national digits and the North American Numbering Plan ('+1') requires 10.
614	     */
615	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
616	        Map.of("61", 9, "1", 10);
617	
618	    /**
619	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
620	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
621	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
622	     * followed by 8 to 15 digits, and its national-number length must match the one required by its
623	     * country calling code ('+61' requires 9 national digits, '+1' requires 10).
624	     *
625	     * @param telephone the raw telephone value as submitted
626	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
627	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
628	     *                                   national-number length is wrong for its country code
629	     */
630	    private String normalizeTelephone(String telephone) {
631	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
632	        String nationalSignificantNumber;
633	        if (cleaned.startsWith("+")) {
634	            nationalSignificantNumber = cleaned.substring(1);
635	        } else {
636	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
637	            nationalSignificantNumber = "61" + national;
638	        }
639	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
640	            throw new InvalidTelephoneException(telephone);
641	        }
642	        validateNationalNumberLength(nationalSignificantNumber, telephone);
643	        return "+" + nationalSignificantNumber;
644	    }
645	
646	    /**
647	     * Validates the national-number length of an E.164 number against its country calling code. The
648	     * significant number is a country code immediately followed by the national digits; for each
649	     * known code in {@link #NATIONAL_NUMBER_LENGTHS} the remaining national digits must number
650	     * exactly the required amount ('+61' requires 9, '+1' requires 10). Codes with no known rule are
651	     * left unchecked.
652	     *
653	     * @param nationalSignificantNumber the E.164 digits following the '+' (country code + national)
654	     * @param rejectedValue             the raw telephone value, reported on rejection
655	     * @throws InvalidTelephoneException if the national-number length is wrong for the country code
656	     */
657	    private void validateNationalNumberLength(String nationalSignificantNumber, String rejectedValue) {
658	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
659	            String countryCode = rule.getKey();
660	            if (nationalSignificantNumber.startsWith(countryCode)) {
661	                int nationalDigits = nationalSignificantNumber.length() - countryCode.length();
662	                if (nationalDigits != rule.getValue()) {
663	                    throw new InvalidTelephoneException(rejectedValue);
664	                }
665	                return;
666	            }
667	        }
668	    }
669	
670	    /**
671	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
672	     * value is treated as absent and returns {@code null}); when present the value must be a
673	     * syntactically valid address, and is stored and returned lower-cased.
674	     *
675	     * @param email the raw email value as submitted, may be {@code null}
676	     * @return the lower-cased email, or {@code null} when none was supplied
677	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
678	     */
679	    private String normalizeEmail(String email) {
680	        if (email == null || email.isBlank()) {
681	            return null;
682	        }
683	        String normalized = email.trim().toLowerCase();
684	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
685	            throw new InvalidEmailException(email);
686	        }
687	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
688	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
689	            throw new DisposableEmailException(email);
690	        }
691	        return normalized;
692	    }
