694	    /**
695	     * The single, consolidated duplicate check. Rejects the owner being created when its whole
696	     * {@link #identityKey(Owner) identityKey} exactly equals that of an existing owner. Because the
697	     * key is the normalized telephone, email and householdId joined together, this one check
698	     * subsumes the former separate telephone, email and household duplicate rules: only an exact
699	     * full-key match counts as a duplicate, so two members of the same household (same householdId)
700	     * with different telephones have different keys and are both allowed.
701	     *
702	     * @param owner the owner being created, with its normalized telephone, email and householdId
703	     *              already applied
704	     * @throws DuplicateIdentityException if another owner already has the same identityKey
705	     */
706	    private void rejectDuplicateIdentity(Owner owner) {
707	        String identityKey = identityKey(owner);
708	        boolean inUse = this.clinicService.findAllOwners().stream()
709	            .filter(existing -> !isDeleted(existing))
710	            .map(this::identityKey)
711	            .anyMatch(identityKey::equals);
712	        if (inUse) {
713	            throw new DuplicateIdentityException(identityKey);
714	        }
715	    }
716	
717	    /**
718	     * Derives an owner's {@code identityKey}: {@code normalizedTelephone + '|' + (email or empty) +
719	     * '|' + householdId}. A {@code null} email or householdId contributes an empty segment. Every
720	     * duplicate decision is made by comparing whole identityKeys.
721	     *
722	     * @param owner the owner whose identityKey to derive
723	     * @return the derived identityKey
724	     */
725	    private String identityKey(Owner owner) {
726	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
727	        String email = owner.getEmail() == null ? "" : owner.getEmail();
728	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
729	        return telephone + "|" + email + "|" + householdId;
730	    }
731	
732	    /**
733	     * Applies the household rule to an owner being created. The household is keyed on
734	     * (lastName, postcode): the owner is assigned the deterministic {@link #householdId(Owner)
735	     * householdId} derived from its normalized lastName and postcode, so owners sharing a lastName
736	     * and postcode automatically share the identifier — the link is computed, not created by a flag.
737	     *
738	     * <p>Because the household is keyed on (lastName, postcode), any existing owner that derives the
739	     * same householdId is a member of the same household, and a second owner joining it is a
740	     * household duplicate. Such a create is rejected with 409 unless the request declares
741	     * {@code sharesHousehold=true}, in which case it is allowed through as a declared household
742	     * member. The {@code sharesHousehold} directive only bypasses this duplicate block.
743	     *
744	     * @param owner           the owner being created
745	     * @param sharesHousehold whether the request declared it shares a household, bypassing the block
746	     * @throws HouseholdDuplicateException if an existing owner already shares the household and the
747	     *                                     request did not declare {@code sharesHousehold=true}
748	     */
749	    private void applyHousehold(Owner owner, boolean sharesHousehold) {
750	        String householdId = householdId(owner);
751	        owner.setHouseholdId(householdId);
752	        boolean householdExists = this.clinicService.findAllOwners().stream()
753	            .filter(existing -> !isDeleted(existing))
754	            .anyMatch(existing -> householdId.equals(householdId(existing)));
755	        if (householdExists && !sharesHousehold) {
756	            throw new HouseholdDuplicateException(householdId);
757	        }
758	    }
759	
760	    /**
761	     * Derives the stable, shared household identifier for an owner, formatted {@code HH-<HEX12>}
762	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the owner's normalized
763	     * lastName, a {@code '|'} separator, and its postcode. Being a pure function of (lastName,
764	     * postcode), every owner sharing a lastName and postcode derives the same value regardless of
765	     * creation order. A {@code null} postcode contributes an empty segment.
766	     *
767	     * @param owner the owner whose household identifier to derive
768	     * @return the household identifier
769	     */
770	    private String householdId(Owner owner) {
771	        String lastNameKey = toHouseholdKey(owner.getLastName());
772	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
773	        try {
774	            byte[] digest = MessageDigest.getInstance("SHA-256")
775	                .digest((lastNameKey + "|" + postcode).getBytes(StandardCharsets.UTF_8));
776	            StringBuilder hex = new StringBuilder(digest.length * 2);
777	            for (byte b : digest) {
778	                hex.append(String.format("%02x", b));
779	            }
780	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
781	        } catch (NoSuchAlgorithmException ex) {
782	            throw new IllegalStateException("SHA-256 not available", ex);
783	        }
784	    }
785	
786	    /**
787	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
788	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
789	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
790	     * string.
791	     */
792	    private String toHouseholdKey(String value) {
793	        if (value == null) {
794	            return "";
795	        }
796	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
797	    }
798	
799	    /**
800	     * Applies the owner's address, preferring the structured form over the flat one. The structured
801	     * {@code addressLine1}/{@code addressLine2} and the flat {@code address} are each normalized (see
802	     * {@link #normalizeAddress(String)}). When a non-blank {@code addressLine1} is supplied the
803	     * structured form wins: {@code addressLine1} and {@code addressLine2} are stored normalized (a
804	     * blank {@code addressLine2} is stored as {@code null}), and the composed {@code address} is the
805	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
806	     * appended when an {@code addressLine2} is present. Otherwise the flat {@code address} is used for
807	     * backward compatibility: the normalized flat value becomes both {@code addressLine1} and the
808	     * stored {@code address}, with no {@code addressLine2}. Everything that later reads the owner's
809	     * address therefore sees the structured value when present, falling back to the flat one.
810	     *
811	     * @param owner the owner being created
812	     * @param dto   the submitted owner fields
813	     */
814	    private void applyAddress(Owner owner, OwnerFieldsDto dto) {
815	        String line1 = normalizeAddress(dto.getAddressLine1());
816	        String line2 = normalizeAddress(dto.getAddressLine2());
817	        String flat = normalizeAddress(dto.getAddress());
818	        String effectiveLine1 = line1.isEmpty() ? flat : line1;
819	        String effectiveLine2 = line1.isEmpty() ? "" : line2;
820	        String composed = effectiveLine2.isEmpty()
821	            ? effectiveLine1
822	            : effectiveLine1 + " " + effectiveLine2;
823	        owner.setAddressLine1(effectiveLine1.isEmpty() ? null : effectiveLine1);
824	        owner.setAddressLine2(effectiveLine2.isEmpty() ? null : effectiveLine2);
825	        owner.setAddress(composed);
826	    }
827	
828	    /**
829	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
830	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
831	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
832	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
833	     * value, or one that is blank once trimmed, normalizes to an empty string.
834	     *
835	     * @param address the raw address value as submitted, may be {@code null}
836	     * @return the normalized address, or an empty string when none was supplied
837	     */
838	    private String normalizeAddress(String address) {
839	        if (address == null) {
840	            return "";
841	        }
842	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
843	        if (collapsed.isEmpty()) {
844	            return "";
845	        }
846	        String[] tokens = collapsed.split(" ");
847	        StringBuilder normalized = new StringBuilder(collapsed.length());
848	        for (int i = 0; i < tokens.length; i++) {
849	            if (i > 0) {
850	                normalized.append(' ');
851	            }
852	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
853	        }
854	        return normalized.toString();
855	    }
