254	     * tenure exceeds {@value #TENURE_POINTS_FISCAL_YEARS} elapsed fiscal year(s).
255	     */
256	    protected Integer membershipPoints(Owner owner) {
257	        int points = 0;
258	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
259	        if (hasEmail) {
260	            points += 2;
261	        }
262	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
263	        if (noNamesakes) {
264	            points += 1;
265	        }
266	        if (householdSize(owner) >= HOUSEHOLD_POINTS_SIZE) {
267	            points += 2;
268	        }
269	        if (tenureFiscalYears(owner) > TENURE_POINTS_FISCAL_YEARS) {
270	            points += 3;
271	        }
272	        return points;
273	    }
274	
275	    /**
276	     * Derives the owner's membership level from their {@link #membershipPoints(Owner) membership
277	     * points}: level 1 for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or more.
278	     */
279	    protected Integer membershipLevel(Owner owner) {
280	        int points = membershipPoints(owner);
281	        if (points <= 1) {
282	            return 1;
283	        }
284	        if (points <= 3) {
285	            return 2;
286	        }
287	        if (points <= 5) {
288	            return 3;
289	        }
290	        return 4;
291	    }
