293	    /**
294	     * The number of owners in this owner's household — the count of owners (including this one)
295	     * sharing its {@code householdId}. Returns 0 when the owner has no household identifier.
296	     */
297	    private long householdSize(Owner owner) {
298	        String householdId = owner.getHouseholdId();
299	        if (householdId == null) {
300	            return 0;
301	        }
302	        return this.clinicService.findAllOwners().stream()
303	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
304	            .count();
305	    }
306	
307	    /**
308	     * The owner's tenure in elapsed fiscal years: the number of fiscal years (each starting 1 July)
309	     * between their {@code registrationDate} and the current date, i.e. the current fiscal year less
310	     * the registration date's fiscal year. Returns 0 when no registration date is present, so an
311	     * owner without a registration date is treated as having no tenure.
312	     */
313	    private long tenureFiscalYears(Owner owner) {
314	        LocalDate registrationDate = owner.getRegistrationDate();
315	        if (registrationDate == null) {
316	            return 0;
317	        }
318	        return (long) fiscalYearOf(LocalDate.now()) - fiscalYearOf(registrationDate);
319	    }
320	
321	    /**
322	     * Flags a bulk-signup day: {@code true} once more than {@link #BULK_SIGNUP_THRESHOLD} other
323	     * owners already carry this owner's {@code registrationDate}. The owner itself is excluded from
324	     * the count, so on a create the flag reflects the owners that pre-existed it that day, matching
325	     * the accumulation the per-day create limit is enforced against. Returns {@code false} when the
326	     * owner has no registration date.
327	     */
328	    protected Boolean bulkSignupWarning(Owner owner) {
329	        LocalDate registrationDate = owner.getRegistrationDate();
330	        if (registrationDate == null) {
331	            return false;
332	        }
333	        long othersOnDay = this.clinicService.findAllOwners().stream()
334	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
335	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
336	            .count();
337	        return othersOnDay > BULK_SIGNUP_THRESHOLD;
338	    }
339	
340	    /**
341	     * Derives the owner's {@code checkDigit}: the Luhn check digit (0-9) computed over the digits
342	     * contained in the owner's {@code customerCode}. Non-digit characters are ignored. Returns
343	     * {@code null} when no customer code has been assigned.
344	     */
345	    protected Integer checkDigit(Owner owner) {
346	        String customerCode = owner.getCustomerCode();
347	        if (customerCode == null) {
348	            return null;
349	        }
350	        int sum = 0;
351	        boolean dbl = true;
352	        for (int i = customerCode.length() - 1; i >= 0; i--) {
353	            char c = customerCode.charAt(i);
354	            if (c < '0' || c > '9') {
355	                continue;
356	            }
357	            int d = c - '0';
358	            if (dbl) {
359	                d *= 2;
360	                if (d > 9) {
361	                    d -= 9;
362	                }
363	            }
364	            sum += d;
365	            dbl = !dbl;
366	        }
367	        return (10 - (sum % 10)) % 10;
368	    }
369	
370	    /**
371	     * Derives the owner's {@code salutation}: the owner's {@code title} and {@code lastName}
372	     * separated by a single space (e.g. {@code DR Franklin}), or just the {@code lastName} when no
373	     * title was supplied (a {@code null} or blank title).
374	     */
375	    protected String salutation(Owner owner) {
376	        String title = owner.getTitle();
377	        String lastName = owner.getLastName();
378	        if (title == null || title.isBlank()) {
379	            return lastName;
380	        }
381	        return title + " " + lastName;
382	    }
