386	     * {@code /api/owners/<id>} using the owner's id. Returns {@code null} when the owner has no id.
387	     */
388	    protected String selfLink(Owner owner) {
389	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
390	    }
